const workPackage = $json.text;

const timestamp = new Intl.DateTimeFormat("sv-SE", {
  timeZone: "Europe/Berlin",
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hour12: false,
}).format(new Date()).replace(" ", " ");

return [{
  json: {
    output: `> Generated: ${timestamp} Europe/Berlin

${workPackage}`
  }
}];
